/* Publication and people explorers use the same Excel-backed records. */
const publicationParams=new URLSearchParams(location.search);
const publicationState={q:publicationParams.get('q')||'',view:publicationParams.get('view')==='high'?'high':'all',theme:publicationParams.get('theme')||'',person:publicationParams.get('person')||'',year:publicationParams.get('year')||'',journal:publicationParams.get('journal')||'',cover:publicationParams.get('cover')==='1'};
let publicationLimit=20;
const allPublications=()=>cms?.publications||[];
const allMembers=()=>[...profiles,...(cms?.students||[]),...staff,...(cms?.alumni||[])];
function publicationRow(p){return `<article class="paper-row" id="${p.id}">${p.cover?`<img class="paper-thumb" src="${p.cover}" alt="${copy(p.title)}" loading="lazy">`:''}<div><p class="paper-journal">${escapeHtml(p.journal)}${p.year?' · '+p.year:''}${p.featured?`<span>${t('精选','Highlight')}</span>`:''}</p><h3>${p.url?`<a href="${escapeHtml(p.url)}" target="_blank" rel="noopener">${copy(p.title)} ↗</a>`:copy(p.title)}</h3><p class="paper-authors">${escapeHtml(p.authors)}</p><div class="paper-topics">${p.categories.map(id=>{const c=cms.publicationCategories.find(c=>c.id===id);return c?`<a href="publications.html?theme=${encodeURIComponent(id)}">${copy(c.title)}</a>`:''}).join('')}</div><details class="paper-details"><summary>${t('引文与详情','Citation & details')}</summary><p>${escapeHtml(p.citation)}</p>${p.abstract.zh?`<p>${copy(p.abstract)}</p>`:''}${p.url?`<a class="text-link" href="${escapeHtml(p.url)}" target="_blank" rel="noopener">${t('阅读论文','Read paper')} ↗</a>`:''}</details></div></article>`;}
function renderPublicationExplorer(){const pubs=allPublications(),categories=cms?.publicationCategories||[],years=[...new Set(pubs.map(p=>p.year).filter(Boolean))].sort((a,b)=>b-a),journals=[...new Set(pubs.map(p=>p.journal).filter(Boolean))].sort();const options=(items,value)=>items.map(v=>`<option value="${escapeHtml(v)}" ${String(value)===String(v)?'selected':''}>${escapeHtml(v)}</option>`).join('');
return titleBlock('PUBLICATIONS','论文与著作','Papers & books',t('从研究主题、年份、期刊或团队成员出发，探索我们的学术工作。','Explore our work by research theme, year, journal or team member.'))+researchSubnav()+`<section class="section page-body publication-page">${pubs.some(p=>p.cover)?`<section class="cover-section"><h2>${t('封面成果','On the cover')}</h2><div class="cover-shelf">${pubs.filter(p=>p.cover).map(p=>`<a href="#${p.id}" data-cover-paper="${p.id}"><img src="${p.cover}" alt="${copy(p.title)}" loading="lazy"><span>${escapeHtml(p.journal)} · ${p.year}</span></a>`).join('')}</div></section>`:''}<div class="publication-head"><div class="publication-tabs" role="group" aria-label="${t('论文列表范围','Publication view')}"><button data-publication-view="high" aria-pressed="${publicationState.view==='high'}">${t('精选论文','Highlights')}</button><button data-publication-view="all" aria-pressed="${publicationState.view==='all'}">${t('完整列表','Full list')}</button></div><label class="publication-search"><span>${t('检索论文','Search papers')}</span><input id="paper-search" type="search" value="${escapeHtml(publicationState.q)}" placeholder="${t('搜索标题、作者、期刊…','Search titles, authors, journals…')}"></label></div><div class="topic-filters" role="group" aria-label="${t('研究主题','Research themes')}"><button data-publication-theme="" aria-pressed="${!publicationState.theme}">${t('全部主题','All themes')}</button>${categories.map(c=>`<button data-publication-theme="${c.id}" aria-pressed="${publicationState.theme===c.id}">${copy(c.title)} <span>${pubs.filter(p=>p.categories.includes(c.id)).length}</span></button>`).join('')}</div><div class="publication-selects"><label>${t('年份','Year')}<select id="paper-year"><option value="">${t('全部年份','All years')}</option>${options(years,publicationState.year)}</select></label><label>${t('期刊 / 出版社','Journal / publisher')}<select id="paper-journal"><option value="">${t('全部期刊及出版社','All journals & publishers')}</option>${options(journals,publicationState.journal)}</select></label><label>${t('团队成员','Team member')}<select id="paper-person"><option value="">${t('全部成员','All members')}</option>${allMembers().map(p=>`<option value="${p.id}" ${publicationState.person===p.id?'selected':''}>${copy(p.name)}</option>`).join('')}</select></label><label class="cover-check"><input id="paper-cover" type="checkbox" ${publicationState.cover?'checked':''}>${t('仅封面成果','Covers only')}</label><button type="button" id="paper-reset">${t('清除筛选','Clear filters')} ↺</button></div><p class="catalog-note">${t('收录已整理的代表性论文与著作，后续持续补充。','A growing collection of selected papers and books from the team.')}</p><p id="paper-count" class="paper-count" aria-live="polite"></p><div id="paper-list"></div><button id="paper-more" class="catalog-more" hidden>${t('显示更多','Show more')}</button><details class="journal-directory"><summary>${t('按期刊浏览','Browse by journal')}</summary><div>${journals.map(j=>`<button data-publication-journal="${escapeHtml(j)}">${escapeHtml(j)} <span>${pubs.filter(p=>p.journal===j).length}</span></button>`).join('')}</div></details></section>`;}
function updatePublicationResults(){const list=PublicationCatalog.filter(allPublications(),publicationState),el=document.getElementById('paper-list');if(!el)return;const shown=list.slice(0,publicationLimit);let previous=null;el.innerHTML=shown.map(p=>{const year=p.year||t('年份未注明','Year unspecified'),head=year!==previous?`<h2 class="paper-year-heading">${year}</h2>`:'';previous=year;return head+publicationRow(p);}).join('')||`<div class="catalog-empty"><h2>${t('没有符合条件的论文','No matching papers')}</h2><p>${t('试试其他关键词，或清除筛选。','Try another keyword or clear the filters.')}</p></div>`;document.getElementById('paper-count').textContent=t(`找到 ${list.length} 项 · 已显示 ${shown.length} 项`,`Found ${list.length} items · Showing ${shown.length}`);document.getElementById('paper-more').hidden=shown.length>=list.length;
document.querySelectorAll('[data-publication-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.publicationView===publicationState.view)));document.querySelectorAll('[data-publication-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.publicationTheme===publicationState.theme)));const url=new URL(location.href);for(const [key,value]of Object.entries(publicationState)){if(value&&!(key==='view'&&value==='all'))url.searchParams.set(key,value===true?'1':value);else url.searchParams.delete(key);}history.replaceState(null,'',url);}
function memberPaperLink(id){return 'publications.html?person='+encodeURIComponent(id);}
function memberCard(p){const papers=allPublications().filter(x=>x.personIds.includes(p.id));return `<article class="member-card" data-member="${p.id}"><button class="member-open" data-member-open="${p.id}" aria-expanded="false"><div class="member-photo"><img src="${p.photo}" alt="${copy(p.name)}" loading="lazy"></div><h3>${copy(p.name)}</h3><p>${copy(p.role)}</p>${p.entryYear||p.graduationYear?`<p class="member-years">${p.entryYear||''}${p.entryYear&&p.graduationYear?'–':''}${p.graduationYear||''}</p>`:''}<span>${t('简介与论文','Profile & papers')} · ${papers.length} ↗</span></button>${p.group==='导师'?`<a class="member-cv-link" href="profile-${p.id}.html">${t('完整学术履历','Full academic profile')} ↗</a>`:''}</article>`;}
function renderPeopleDirectory(){const leader=profiles.find(p=>p.id==='zhu'),members=page==='people'?profiles.filter(p=>p.id!=='zhu'):page==='staff'?staff:(cms?.[page]||[]),label=pageNames[page];let body='';if(page==='people')body=`<section class="group-leader"><a class="leader-photo" href="profile-zhu.html"><img src="${leader.photo}" alt="${copy(leader.name)}"></a><div><p class="eyebrow dark">GROUP LEADER</p><h2>${copy(leader.name)}</h2><p class="leader-role">${copy(leader.role)}</p><p class="leader-intro">${copy(leader.intro)}</p><div class="leader-links"><a href="profile-zhu.html">${t('完整学术履历','Full academic profile')} ↗</a><a href="${memberPaperLink('zhu')}">${t('相关论文','Related publications')} ↗</a></div><details class="leader-career"><summary>${t('教育工作经历与荣誉','Career & recognition')}</summary>${leader.experience.length?list(leader.experience,false):''}${leader.awards.length?list(leader.awards,false):''}</details></div></section>`;
return titleBlock('OUR PEOPLE','人员队伍','Our people',t('因共同的研究兴趣而相聚，向绿色钢铁的未来探索。','A shared curiosity. A collective pursuit of greener steel.'))+peopleNav()+`<section class="section page-body people-catalog">${body}<div class="member-section-heading"><h2>${page==='people'?t('导师团队','Faculty'):t(...label)}</h2><span>${members.length}${t(' 位成员',' members')}</span></div>${members.length?`<div class="member-grid">${members.map(memberCard).join('')}</div>`:`<div class="catalog-empty"><h3>${t(page==='students'?'学生名单待补充':'毕业生名录待补充',page==='students'?'Student directory to be added':'Alumni directory to be added')}</h3><p>${t('名单补充后将按人员分区展示照片、培养层次及相关论文。','Photos, academic roles and related papers will appear as the directory is updated.')}</p></div>`}</section>`;}
function openMemberPanel(id){const card=document.querySelector(`[data-member="${id}"]`),p=allMembers().find(p=>p.id===id);if(!card||!p)return;const old=document.querySelector('.member-panel'),same=old?.dataset.for===id;old?.remove();document.querySelectorAll('[data-member-open]').forEach(b=>b.setAttribute('aria-expanded','false'));if(same)return;const papers=PublicationCatalog.filter(allPublications(),{person:id}),panel=document.createElement('section');panel.className='member-panel';panel.dataset.for=id;panel.innerHTML=`<div class="member-panel-heading"><h3>${copy(p.name)} · ${t('简介与论文','Profile & papers')}</h3><button data-member-close aria-label="${t('关闭简介','Close profile')}">×</button></div>${p.intro.zh?`<p>${copy(p.intro)}</p>`:''}${p.office?.zh?`<p>${t('办公地点：','Office: ')}${copy(p.office)}</p>`:''}${p.fields?.length?`<p>${p.fields.map(copy).join(' · ')}</p>`:''}<h4>${papers.length}${t(' 项相关论文与著作',' related papers & books')}</h4>${papers.length?`<ol>${papers.slice(0,4).map(x=>`<li><a href="${memberPaperLink(id)}#${x.id}">${copy(x.title)}</a><span>${escapeHtml(x.journal)} · ${x.year}</span></li>`).join('')}</ol><a class="text-link" href="${memberPaperLink(id)}">${t('在论文库中查看全部','Explore all related publications')} ↗</a>`:`<p>${t('相关论文待补充。','Related publications to be added.')}</p>`}${p.group==='导师'?`<a class="text-link" href="profile-${id}.html">${t('完整学术履历','Full academic profile')} ↗</a>`:''}`;const rowTop=card.offsetTop;const row=[...card.parentElement.querySelectorAll('.member-card')].filter(c=>Math.abs(c.offsetTop-rowTop)<5);row.at(-1).after(panel);card.querySelector('button').setAttribute('aria-expanded','true');panel.querySelector('[data-member-close]').onclick=()=>{panel.remove();card.querySelector('button').setAttribute('aria-expanded','false');card.querySelector('button').focus();};}
function bindExplorer(){if(page==='publications'){updatePublicationResults();const update=()=>{publicationLimit=20;updatePublicationResults();};document.getElementById('paper-search').oninput=e=>{publicationState.q=e.target.value;update();};for(const [id,key]of [['paper-year','year'],['paper-journal','journal'],['paper-person','person']])document.getElementById(id).onchange=e=>{publicationState[key]=e.target.value;update();};document.getElementById('paper-cover').onchange=e=>{publicationState.cover=e.target.checked;update();};document.querySelectorAll('[data-publication-view]').forEach(b=>b.onclick=()=>{publicationState.view=b.dataset.publicationView;update();});document.querySelectorAll('[data-publication-theme]').forEach(b=>b.onclick=()=>{publicationState.theme=b.dataset.publicationTheme;update();});document.querySelectorAll('[data-publication-journal]').forEach(b=>b.onclick=()=>{publicationState.journal=b.dataset.publicationJournal;document.getElementById('paper-journal').value=publicationState.journal;update();document.getElementById('paper-count').scrollIntoView({block:'center'});});document.getElementById('paper-reset').onclick=()=>{Object.assign(publicationState,{q:'',view:'all',theme:'',person:'',year:'',journal:'',cover:false});render();};document.getElementById('paper-more').onclick=()=>{publicationLimit+=20;updatePublicationResults();};document.querySelectorAll('[data-cover-paper]').forEach(a=>a.onclick=()=>{Object.assign(publicationState,{q:'',view:'all',theme:'',person:'',year:'',journal:'',cover:false});render();});}document.querySelectorAll('[data-member-open]').forEach(b=>b.onclick=()=>openMemberPanel(b.dataset.memberOpen));}
